DOCUMENT();
############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "niceTables.pl", "parserAssignment.pl", "contextForm.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
@x = random_subset(5, 0..19); $b = non_zero_random(-9, 9); $f = Formula("x + $b")->reduce; @y = map{$f->eval(x => $_)} (@x); Context("Numeric")->variables->add(y => 'Real'); parser::Assignment->Allow; $eq = Formula("y = $f"); $absb = abs($b); $compstring = ($b > 0) ? 'more' : 'less';
############################# # Exercise Group Introduction #############################
BEGIN_PGML Write an equation in the form [`y=\ldots`] suggested by the pattern in the table.
END_PGML
###### # Body ######
BEGIN_PGML >> [@DataTable( [ [ [PGML('[`x`]'), rowbottom => '2', midrule => '1',], PGML('[`y`]'), ], [ PGML('[`[$x[0]]`]'), PGML('[`[$y[0]]`]'), ], [ PGML('[`[$x[1]]`]'), PGML('[`[$y[1]]`]'), ], [ PGML('[`[$x[2]]`]'), PGML('[`[$y[2]]`]'), ], [ PGML('[`[$x[3]]`]'), PGML('[`[$y[3]]`]'), ], [ PGML('[`[$x[4]]`]'), PGML('[`[$y[4]]`]'), ], ], align => 'rl', valign => 'middle',);@]* <<
[_]{$eq}{20}
END_PGML
########## # Solution ##########
BEGIN_PGML_SOLUTION Each [`y`]-value is [`[$absb]`] [$compstring] than the corresponding [`x`]-value. So the equation is [`[$eq]\text{.}`]
END_PGML_SOLUTION
############# # End Problem #############
ENDDOCUMENT();
